void append_checksum_to_control_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        __sum16 sum = skb_checksum(skb, tlen, offset, 0);
        tlen += offset;
        skb->csum = csum_sub(skb->csum, sum);
    }

    msg->msg_control = skb->ip_summed;
    msg->msg_controllen = sizeof(skb->ip_summed);
}

void append_checksum_to_ctl(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset)
{
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        __sum16 partial_csum = csum_partial(skb->data, offset, 0);
        skb->csum = csum_sub(skb->csum, partial_csum);
    }

    msg->msg_controllen = CMSG_SPACE(sizeof(__sum16));
    struct cmsghdr *cmsg = CMSG_FIRSTHDR(msg);
    cmsg->cmsg_level = SOL_IP;
    cmsg->cmsg_type = IP_RECV_CHECKSUM;
    cmsg->cmsg_len = CMSG_LEN(sizeof(__sum16));
    *(__sum16 *)CMSG_DATA(cmsg) = skb->csum;
}

void append_checksum_to_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset)
{
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        u16 old_csum = skb->csum;
        skb->csum = 0;
        skb->ip_summed = CHECKSUM_NONE;
        skb->csum = csum_partial(skb->data + tlen, skb->len - tlen, 0);
        skb->csum = csum_sub(skb->csum, old_csum);
    }

    csum_add_hdr(msg, skb->csum);
}

void append_checksum_to_control_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        u16 partial_csum = skb_checksum(skb, tlen, offset, 0);
        msg->msg_controllen -= sizeof(cmsghdr);
    }

    u16 checksum = csum_tcpudp_magic(skb->nh.iph->saddr, skb->nh.iph->daddr,
                                     skb->len - skb->data_len, IPPROTO_UDP,
                                     skb_checksum(skb, tlen, skb->len - tlen, 0));
    msg->msg_control = (struct cmsghdr *)((u8 *)msg->msg_control + sizeof(cmsghdr));
    ((struct cmsghdr *)msg->msg_control)->cmsg_len = sizeof(cmsghdr) + sizeof(u16);
    ((struct cmsghdr *)msg->msg_control)->cmsg_level = SOL_IP;
    ((struct cmsghdr *)msg->msg_control)->cmsg_type = IP_TOS;
    memcpy(CMSG_DATA(msg->msg_control), &checksum, sizeof(u16));
}

void append_checksum_to_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        __sum16 partial_csum = skb_checksum(skb, tlen, offset, skb->ip_summed);
        msg->msg_control.user_cookie = (void *)(unsigned long)(*(unsigned long *)msg->msg_control.user_cookie - partial_csum);
    }

    __sum16 total_csum = skb->csum;
    msg->msg_control.user_cookie = (void *)((unsigned long)msg->msg_control.user_cookie + total_csum);
}
